	\begin{tikzpicture}[scale=1.2]

	%Setting features

	\def\psize{2.5mm}
	\def\pcolor{red}
	\def\maincolor{black}
	\def\anglecolor{orangepeel}
	\def\rightanglecolor{deepskyblue}
	\def\vectcol{deepskyblue}
	\def\textcol{black}
	\def\textthickness{thick}

	% Points
	\coordinate (A) at (0,0);
	\coordinate (a) at (5,0);
	\coordinate (M') at (-0.5,0);
	\coordinate (N') at (-2.2,0);
	\tkzDefPointBy[rotation = center A angle 45](a) \tkzGetPoint{B}
	\tkzDefPointBy[projection=onto A--a](B) \tkzGetPoint{C}
	\path (A)--++(90:0.3) coordinate (A');
	\tkzDefPointBy[translation=from A to A'](B) \tkzGetPoint{M'}
	\path (M')--++(90:1) coordinate (N');
	%\tkzDefPointBy[homothety=center A ratio 1.05](B) \tkzGetPoint{P'}
	%\tkzDefPointBy[homothety=center A ratio 1.3](B) \tkzGetPoint{Q'}

