	\tkzLabelPoint[below, yshift=-3pt](A){$C$};
	\tkzLabelPoint[right,yshift=0pt](B){$B$};
	%\tkzLabelPoint[below, yshift=-3pt](C){$B$};

	%Angles	
	\tkzMarkAngle[color=\anglecolor, fill, size=0.9](C,A,B)
	\tkzMarkAngle[color=\vectcol, size=1.1, arrows=-stealth, \textthickness](C,A,B)
	\tkzLabelAngle[pos=1.4, xshift=-2pt, yshift=-1pt](C,A,B){\small $\theta$}
	\tkzMarkRightAngle[color=\rightanglecolor, fill, size=0.4](B,C,A)

	% Triangle
	\tkzDrawSegment[very thick,color=\maincolor](B,A);
	\tkzDrawSegment[dashed, thin](A,C);
	\tkzDrawSegment[dashed, thin](C,B);	

	% Side labels
	\tkzLabelSegment[right](C,B){\small $y$}
	%\tkzLabelSegment[below](A,C){$x$}
	\tkzLabelSegment[sloped,above](A,B){$z=120\,\textrm{cm}$};

	% Vector	

	\tkzDrawVector[color=\vectcol, \textthickness](M',N');
	\tkzLabelSegment[color=\textcol,right](M',N'){$2\,\textrm{cm/s}$}

	% Dots
	\tkzDrawPoints[size=\psize, color=none, fill=\pcolor](B);	

	\end{tikzpicture}
